window.AUTH=window.AUTH||{};window.AUTH["22-666"]={"d":"22-666","id":"2023/22-666","n":"Wilkinson v. Garland","briefs":[{"k":"petitioner","label":"Brief of petitioner Situ Kamu Wilkinson","date":"2023-08-29","url":"https://www.supremecourt.gov/DocketPDF/22/22-666/278461/20230829185728155_22-666%20Wilkinson%20v.%20Garland%20--%20Brief%20for%20Petitioner.pdf","side":"pet","n":73},{"k":"respondent","label":"Brief of respondent Garland, Attorney General of the United States","date":"2023-10-18","url":"https://www.supremecourt.gov/DocketPDF/22/22-666/285479/20231018181204435_22-666bsUnitedStates.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner Situ Kamu Wilkinson","date":"2023-11-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-666/289933/20231117124130757_Wilkinson%20-%20Yellow%20Brief%20-%2017%20November%202023.pdf","side":"pet","n":54}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r10_k5fm.pdf","tr":true,"items":[{"t":"case","label":"Aguilar-Osorio v. Garland","cite":"991 F.3d 997","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/997/","by":{"0":"34","1":"47"}},{"t":"case","label":"Alvarado v. Holder","cite":"743 F.3d 271","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/743/271/","by":{"0":"42"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"0":"46","1":"2"}},{"t":"case","label":"Boechler, P.C. v. Comm’r of Internal Revenue","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"mark the bounds of a court’s adjudicatory authority,","cite":"142 S. Ct. 1493, 1497"}]},{"t":"case","label":"Bowen v. Mich. Acad. of Fam. Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"mean[s] to prohibit all judicial review.","cite":"476 U.S. 667, 672"}]},{"t":"case","label":"Brown v. INS","cite":"775 F.2d 383","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/775/383/","by":{"0":"44"}},{"t":"case","label":"Castillo-Gutierrez v. Garland","cite":"43 F.4th 477","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/43/477/","by":{"0":"34, 45"}},{"t":"case","label":"Chadha v. INS","cite":"634 F.2d 408","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/634/408/","by":{"0":"44","2":"23"},"q":[{"src":"brief","b":0,"text":"requires a legal determination of a traditional sort, the contents of which are explicated by an orderly history of administrative practice and judicial review and interpretation.","cite":"634 F.2d 408, 426"},{"src":"brief","b":2,"text":"require[d] a legal determination of a traditional sort, the contents of which are explicated by an orderly history of administrative practice and judicial review and interpretation.","cite":"634 F.2d 408, 426"}]},{"t":"case","label":"Cooper Indus., Inc. v. Leatherman Tool Grp.","cite":"532 U.S. 424","y":2001,"id":"2000/99-2035","sc":1,"by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"marked by a simple mathematical formula.","cite":"532 U.S. 424, 434-435"}]},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"by":{"0":"38","2":"15"},"q":[{"src":"argument","who":"Ms. Santos","text":"In cases where court -- courts adopt deferential review for mixed questions like Cooter & Gell and like Village of Lakeridge, the Court still takes pains to emphasize that if appellate -- if -- if district courts or agencies are -- are going outside the guardrails, that appellate courts will be able to intervene and correct misapplications of law, misunderstandings of law, and inconsistent applications of law."}]},{"t":"case","label":"Cortes-Castillo v. INS","cite":"997 F.2d 1199","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/997/1199/","by":{"0":"44"}},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"by":{"0":"35"}},{"t":"case","label":"Direct Mktg. Ass’n v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"by":{"0":"3, 22, 38"},"q":[{"src":"brief","b":0,"text":"rule favoring clear boundaries in the interpretation of jurisdictional statutes.","cite":"575 U.S. 1, 11"}]},{"t":"case","label":"Flores-Alonso v. U.S. Attorney General","cite":"36 F.4th 1095","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/1095/","by":{"0":"33, 34, 38, 46"}},{"t":"case","label":"Foremost Ins. Co. v. Richardson","cite":"457 U.S. 668","y":1982,"id":"1981/80-2134","sc":1,"by":{"0":"23"}},{"t":"case","label":"Galeano-Romero v. Barr","cite":"968 F.3d 1176","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/1176/","by":{"0":"33, 40, 48","1":"32, 47"}},{"t":"case","label":"Garcia-Pascual v. Garland","cite":"62 F.4th 1096","y":2023,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/62/1096/","by":{"0":"35, 39, 47","1":"33"}},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"by":{"0":"44"}},{"t":"case","label":"Gitau v. Sessions","cite":"878 F.3d 429","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/878/429/","by":{"0":"39"}},{"t":"case","label":"Gonzalez Galvan v. Garland","cite":"6 F.4th 552","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/552/","by":{"0":"34, 47"},"q":[{"src":"brief","b":0,"text":"Although the ultimate decision whether to grant cancellation of removal is discretionary in nature, 20 The Eleventh Circuit addressed this very issue at length, including the import of Guerrero-Lasprilla, in its en banc decision in Patel that this Court affirmed. 971 F.3d at 1276-1280. Yet an Eleventh Circuit panel subsequently (and summarily) concluded that it could not review an agency’s hardship determination, and did so without even mentioning Guerrero-Lasprilla or the court’s prior en banc decision in Patel. See Flores-Alonso, 36 F.4th 1095. the four statutory eligibility requirements do not speak of discretion.","cite":"6 F.4th at 560"}]},{"t":"case","label":"Google LLC v. Oracle Am., Inc.","cite":"141 S. Ct. 1183","y":2021,"id":"2020/18-956","sc":1,"by":{"0":"29","1":"19, 35, 36","2":"6"},"q":[{"src":"brief","b":1,"text":"should try to break such a question into its separate factual and legal parts.","cite":"141 S. Ct. 1183, 1199"},{"src":"brief","b":1,"text":"was originally * * * fashioned by judges,","cite":"141 S. Ct. at 1199"}]},{"t":"case","label":"Grable & Sons Metal Prods., Inc. v. Darue Eng’g & Mfg.","cite":"545 U.S. 308","y":2005,"id":"2004/04-603","sc":1,"by":{"0":"36"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"by":{"0":"48"}},{"t":"case","label":"Groff v. DeJoy","cite":"143 S. Ct. 2279","y":2023,"id":"2022/22-174","sc":1,"by":{"0":"27","2":"12"},"q":[{"src":"brief","b":2,"text":"all relevant factors in the case at hand","cite":"143 S. Ct. 2279, 2295"}]},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"by":{"0":"1, 2, 13, 17-18, 20-28, 31, 34-37, 41","1":"9, 12, 14, 16, 17, 23, 35","2":"1, 3, 4, 5, 15, 18, 20, 22"},"q":[{"src":"brief","b":0,"text":"the statutory term ‘questions of law’ includes the application of a legal standard to established facts.","cite":"140 S. Ct. 1062, 1072"},{"src":"brief","b":0,"text":"‘clear and convincing evidence’ of congressional intent to preclude judicial review.","cite":"140 S. Ct. at 1069"},{"src":"brief","b":2,"text":"the erroneous application or interpretation of statutes.","cite":"140 S. Ct. at 1071"},{"src":"argument","who":"Ms. Santos","text":"And as this Court held in Guerrero-Lasprilla, the statutory term \"questions of law\" includes the application of legal standards to settled facts."},{"src":"argument","who":"Ms. Santos","text":"After this Court's decision in Guerrero-Lasprilla, courts have generally reviewed due diligence determinations for abuse of discretion, and so --"},{"src":"argument","who":"Ms. Santos","text":"But one thing that I think is critically important is that those practical considerations the Court said expressly in Guerrero-Lasprilla may be relevant to standard of review, but they're not relevant to whether there's judicial review at all."}]},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"by":{"0":"28"}},{"t":"case","label":"Hernandez v. Ashcroft","cite":"345 F.3d 824","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/345/824/","by":{"0":"38"}},{"t":"case","label":"Hernandez v. Garland","cite":"28 F.4th 917","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/28/917/","by":{"0":"39"}},{"t":"case","label":"Hernandez-Morales v. Attorney General","cite":"977 F.3d 247","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/977/247/","by":{"0":"17, 33, 48, 51","1":"9, 32, 47"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"by":{"0":"22, 23, 38, 39, 42","2":"14"},"q":[{"src":"brief","b":0,"text":"administrative simplicity is a major virtue in a jurisdictional statute.","cite":"559 U.S. 77, 94"},{"src":"brief","b":0,"text":"[c]omplex jurisdictional tests complicate a case, eating up time and money as the parties litigate","cite":"559 U.S. at 94"},{"src":"brief","b":2,"text":"administrative simplicity is a major virtue in a jurisdictional statute.","cite":"559 U.S. 77, 94"}]},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"0":"9","2":"23"},"q":[{"src":"brief","b":2,"text":"review … whether the Attorney General … properly applied the statutory standards for denying a request for suspension of deportation.","cite":"462 U.S. 919, 957 n.22"}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"8"},"q":[{"src":"brief","b":0,"text":"between eligibility for discretionary relief, on the one hand, and the favorable exercise of discretion, on the other hand.","cite":"533 U.S. 289, 307"}]},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"by":{"0":"8, 46","1":"42, 43","2":"9, 21, 25"},"q":[{"src":"brief","b":0,"text":"Eligibility that was ‘governed by specific statutory standards’ provided ‘a right to a ruling on an applicant’s eligibility,’ even though the actual granting of relief was ‘not a matter of right under any circumstances, but rather is in all cases a matter of grace.’","cite":"351 U.S. 345, 353-354"},{"src":"brief","b":0,"text":"is governed by specific statutory standards.","cite":"351 U.S. 345, 353"}]},{"t":"case","label":"Kalaw v. INS","cite":"133 F.3d 1147","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/1147/","by":{"0":"51"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"21, 36, 49"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"compliance with the law would rest in the [agency’s] hands alone.","cite":"575 U.S. 480, 488"},{"src":"brief","b":0,"text":"the [government] bears a heavy burden in attempting to show that Congress prohibited all judicial review of the agency’s compliance with a legislative mandate.","cite":"575 U.S. at 486"}]},{"t":"case","label":"Martinez v. Clark","cite":"36 F.4th 1219","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/1219/","by":{"0":"33, 38, 48"},"q":[{"src":"brief","b":0,"text":"[A]n inquiry is discretionary where it is a subjective question that depends on the value judgment of the person or entity examining the issue.","cite":"36 F.4th at 1227"}]},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"legislates with knowledge of [this Court’s] basic rules of statutory construction,","cite":"498 U.S. 479, 496"}]},{"t":"case","label":"Mendez-Castro v. Mukasey","cite":"552 F.3d 975","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/552/975/","by":{"0":"38, 40"}},{"t":"case","label":"Mendez-Moranchel v. Ashcroft","cite":"338 F.3d 176","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/338/176/","by":{"0":"51"}},{"t":"case","label":"Miller v. Fenton","cite":"474 U.S. 104","y":1985,"id":"1985/84-5786","sc":1,"by":{"0":"38","1":"35, 36","2":"6"}},{"t":"case","label":"41, 43, 44, 47 Morales Ventura v. Ashcroft","cite":"348 F.3d 1259","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/348/1259/","by":{"0":"33, 48"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"by":{"0":"27","1":"20, 21, 25, 29","2":"18"},"q":[{"src":"brief","b":0,"text":"historical facts … amount to reasonable suspicion or to probable cause","cite":"572 U.S. 545, 553-554"},{"src":"brief","b":1,"text":"one that stands out from others.","cite":"572 U.S. at 554"},{"src":"argument","who":"Ms. Sinzdak","text":"And I would also point to -- to -- to Octane, which recognizes that \"exceptional\" is a term that itself conveys discretion. So I think just because there's discretion at the second step doesn't mean there's not also discretion at the first step."}]},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"by":{"0":"28, 29","2":"11"},"q":[{"src":"brief","b":0,"text":"fluid concepts that take their substantive content from the particular contexts in which the standards are being assessed.","cite":"517 U.S. 690, 696"}]},{"t":"case","label":"Patel v. Garland","cite":"142 S. Ct. 1614","y":2022,"id":"2021/20-979","sc":1,"by":{"0":"11, 13, 26, 27, 35, 37, 45, 50, 46, 49, 50","1":"9, 12-18, 21, 22, 29, 32-34, 41, 42, 46","2":"3, 7, 20, 22, 25"},"q":[{"src":"brief","b":0,"text":"show that he satisfies various threshold requirements established by Congress.","cite":"142 S. Ct. 1614, 1619"},{"src":"brief","b":0,"text":"still forbid appeals of factual determinations—an important category in the removal context.","cite":"142 S. Ct. 1614, 1623"},{"src":"brief","b":2,"text":"undercuts the Government’s efforts to read it in.","cite":"142 S. Ct. at 1624"}]},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"by":{"0":"46"}},{"t":"case","label":"Ponce Flores v. U.S. Attorney General","cite":"64 F.4th 1208","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/64/1208/","by":{"0":"33","1":"32, 47"},"q":[{"src":"brief","b":1,"text":"dress[ing] up [the] claim with legal or constitutional clothing.","cite":"64 F.4th 1208, 1217"}]},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"by":{"0":"38","1":"10, 15, 19, 20, 21, 34, 39","2":"6"},"q":[{"src":"brief","b":1,"text":"mixed question[s] of law and fact of the kind that in some cases may allow an appellate court to review the facts to see if they satisfy some legal","cite":"456 U.S. at 289"},{"src":"argument","who":"Ms. Sinzdak","text":"… ions fall within the exception that permits judicial review of questions of law and constitutional claim -- claims, the Court has to look at the statute and say: Okay, is this a statute that's asking for a legal conclusion, like fair use, or is this a statute that's saying find a fact or -- like in Pullman-Standard where we had intention to discriminate, pure question of fact, or is it a statute where the terminology is saying make a discretionary decision like in Williamsport Wire Rope, where we had the term \"exceptional hardship\" and the Court said that's requiring a -- a discretionary decis …"},{"src":"argument","who":"Ms. Sinzdak","text":"And I -- I -- I think that actually dovetails very neatly with what the Court already said in Pullman-Standard, where it said, you know, intention to discriminate, right, you can -- you -- that's a statutory requirement."},{"src":"argument","who":"Ms. Sinzdak","text":"So I think that Pullman-Standard, Williamsport Wire Rope, and Duberstein are all good examples of cases where you had a statute and it required some subsidiary fact-finding and then the adjudicator had to put those subsidiary facts together to make an ultimate determination that was -- that was exactly the statutory text."}]},{"t":"case","label":"Ray Haluch Gravel Co. v. Central Pension Fund of Int’l Union of Operating Eng’rs & Participating Emp’rs","cite":"571 U.S. 177","y":2014,"id":"2013/12-992","sc":1,"by":{"0":"37"}},{"t":"case","label":"Romero-Torres v. Ashcroft","cite":"327 F.3d 887","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/327/887/","by":{"0":"33, 42, 47, 48"},"q":[{"src":"brief","b":0,"text":"its proper application requires careful attention to the facts and circumstances of each particular case.","cite":"327 F.3d at 891"}]},{"t":"case","label":"Ruiz v. U.S. Attorney General","cite":"73 F.4th 852","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/73/852/","by":{"0":"39"}},{"t":"case","label":"Santos v. Holder","cite":"573 F. App’x 634","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/573/634/","by":{"0":"38"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"We will hear argument next in Case 22-666, Wilkinson versus Garland. Ms. Santos. ORAL ARGUMENT OF JAIME A. SANTOS ON BEHALF OF THE PETITIONER"},{"src":"argument","who":"Justice Barrett","text":"Ms. Santos --"},{"src":"argument","who":"Justice Barrett","text":"Santos, let me try to get at the questions that you've been asked in a different way. What if we -- let's say that I theoretically agree with you that under Guerrero-Lasprilla, mixed questions, including of this sort, would be subject to judicial review."}]},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"by":{"0":"49"}},{"t":"case","label":"Shalala v. Ill. Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"by":{"0":"21"}},{"t":"case","label":"Singh v. Rosen","cite":"984 F.3d 1142","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/984/1142/","by":{"0":"31, 34, 45, 47"},"q":[{"src":"brief","b":0,"text":"prohibit a debtor from obtaining a discharge of certain student-loan debts unless the debts impose an ‘undue hardship’ on the debtor.","cite":"984 F.3d at 1152"},{"src":"brief","b":0,"text":"rested on logic treating the [hardship] conclusion as resolving a mixed question.","cite":"984 F.3d at 1153"}]},{"t":"case","label":"50, 51 Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"avoided in the area of subject-matter jurisdiction wherever possible.","cite":"497 U.S. 358, 375"}]},{"t":"case","label":"Small v. Memphis Light, Gas & Water","cite":"141 S. Ct. 1227","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1227/","sc":1,"by":{"0":"28"}},{"t":"case","label":"Tacuri-Tacuri v. Garland","cite":"998 F.3d 466","y":2021,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/998/466/","by":{"0":"42"}},{"t":"case","label":"Teva Pharms. USA, Inc. v. Sandoz, Inc.","cite":"574 U.S. 318","y":2015,"id":"2014/13-854","sc":1,"by":{"0":"29","1":"47"},"q":[{"src":"argument","who":"Ms. Sinzdak","text":"And we see that in Teva. We see that in Oracle. Is this the sort of thing, question that has been decided by juries or by fact finders? Then it's not going to be -- considered a question of law."}]},{"t":"case","label":"Thompson v. Keohane","cite":"516 U.S. 99","y":1995,"id":"1995/94-6615","sc":1,"by":{"0":"38"}},{"t":"case","label":"Thryv, Inc v. Click-To-Call Techs., LP","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"by":{"0":"21"}},{"t":"case","label":"Tobar-Bautista v. Sessions","cite":"710 F. App’x 506","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/710/506/","by":{"0":"47"}},{"t":"case","label":"Trejo v. Garland","cite":"3 F.4th 760","y":2021,"url":"https://www.courtlistener.com/c/F.4th/3/760/","by":{"0":"45, 50, 51, 52"},"q":[{"src":"brief","b":0,"text":"[c]ourts have not found the question of whether ‘undue hardship’ exists to be so subjective an inquiry.","cite":"3 F.4th 760, 772"}]},{"t":"case","label":"Twum v. Barr","cite":"930 F.3d 10","y":2019,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/930/10/","by":{"0":"39"}},{"t":"case","label":"Valenzuela Alcantar v. INS","cite":"309 F.3d 946","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/946/","by":{"0":"48"}},{"t":"law","label":"Pub. L. No. 80-863","by":{"0":"9"}},{"t":"law","label":"Pub. L. No. 87-885","url":"https://www.govinfo.gov/link/statute/76/1247","by":{"0":"9, 10","1":"3"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"10","1":"2"}},{"t":"law","label":"Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"0":"9, 44, 50"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)(B)(v)","(d)(12)(B)","(h)(1)(B)","(i)(1)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"by":{"0":"50","2":"19, 24, 24"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"reg","label":"8 C.F.R. § 1003.1","url":"https://www.ecfr.gov/current/title-8/section-1003.1","subs":["(d)(3)(i)"],"by":{"0":"6","2":"7"}},{"t":"case","label":"Adeyeye v. Heartland Sweeteners, LLC","cite":"721 F.3d 444","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/721/444/","by":{"1":"38"}},{"t":"case","label":"Amgen Inc. v. Sanofi","cite":"598 U.S. 534","y":2023,"id":"2022/21-757","sc":1,"by":{"1":"34"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"by":{"1":"16"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"by":{"1":"33"}},{"t":"case","label":"Berkovitz v. United States","cite":"486 U.S. 531","y":1988,"id":"1987/87-498","sc":1,"by":{"1":"22","2":"8"}},{"t":"case","label":"Bose Corp. v. Consumers Union of U.S., Inc.","cite":"466 U.S. 485","y":1984,"id":"1983/82-1246","sc":1,"by":{"1":"36"}},{"t":"case","label":"Commissioner v. Duberstein","cite":"363 U.S. 278","y":1960,"id":"1959/376","sc":1,"by":{"1":"20, 21, 29"},"q":[{"src":"argument","who":"Ms. Sinzdak","text":"So I think that Pullman-Standard, Williamsport Wire Rope, and Duberstein are all good examples of cases where you had a statute and it required some subsidiary fact-finding and then the adjudicator had to put those subsidiary facts together to make an ultimate determination that was -- that was exactly the statutory text."}]},{"t":"case","label":"Concepcion v. United States","cite":"142 S. Ct. 2839","y":2022,"id":"2021/20-1650","sc":1,"by":{"1":"43"}},{"t":"case","label":"Dupree v. Younger","cite":"598 U.S. 729","y":2023,"id":"2022/22-210","sc":1,"by":{"1":"47"}},{"t":"case","label":"Gonzalez-Rivas v. Garland","cite":"53 F.4th 1129","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/53/1129/","by":{"1":"47"}},{"t":"case","label":"Hernandez-Cordero v. INS","cite":"819 F.2d 558","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/558/","by":{"1":"28"}},{"t":"case","label":"Hiatt v. Brown","cite":"339 U.S. 103","y":1950,"id":"scdb/1949-052","sc":1,"by":{"1":"22"}},{"t":"case","label":"Highmark Inc. v. Allcare Health Mgmt. Sys., Inc.","cite":"572 U.S. 559","y":2014,"id":"2013/12-1163","sc":1,"by":{"1":"18, 20, 43","2":"9, 18"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"a long history of judicial application.","cite":"560 U.S. 631, 651"}]},{"t":"case","label":"INS v. Hector","cite":"479 U.S. 85","y":1986,"id":"1986/86-21","sc":1,"by":{"1":"27, 28, 44"}},{"t":"case","label":"INS v. Jong Ha Wang","cite":"450 U.S. 139","y":1981,"id":"1980/80-485","sc":1,"by":{"1":"27, 37","2":"23, 24"},"q":[{"src":"brief","b":1,"text":"‘shift the administration of hardship deportation cases from the [agency] to’","cite":"450 U.S. at 146"},{"src":"argument","who":"Ms. Sinzdak","text":"So, in Jong -- Jong Ha Wang --"}]},{"t":"case","label":"INS v. Orlando Ventura","cite":"537 U.S. 12","y":2002,"id":"2002/02-29","sc":1,"by":{"1":"34"}},{"t":"case","label":"INS v. Phinpathya","cite":"464 U.S. 183","y":1984,"id":"1983/82-91","sc":1,"by":{"1":"27","2":"21, 22, 23, 24"}},{"t":"case","label":"Karlin v. Reed","cite":"584 F.2d 365","y":1978,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/584/365/","by":{"1":"38"}},{"t":"case","label":"Kimbro v. Atlantic Richfield Co.","cite":"889 F.2d 869","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/869/","by":{"1":"38"}},{"t":"case","label":"Liu v. United States Dep’t of Justice","cite":"13 F.3d 1175","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/13/1175/","by":{"1":"28"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"by":{"1":"36"}},{"t":"case","label":"McWright v. Alexander","cite":"982 F.2d 222","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/982/222/","by":{"1":"38"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"521 U.S. 121","y":1997,"id":"1996/96-272","sc":1,"by":{"1":"21"}},{"t":"case","label":"Moog Indus. Inc. v. Federal Trade Commission","cite":"355 U.S. 411","y":1958,"id":"1957/77","sc":1,"by":{"1":"22","2":"8"}},{"t":"case","label":"Perez v. Garland","cite":"67 F.4th 254","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/67/254/","by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"categorically foreclose[s] review of hardship determinations.","cite":"67 F.4th 254, 257"}]},{"t":"case","label":"Ramirez-Durazo v. INS","cite":"794 F.2d 491","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/794/491/","by":{"1":"28"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"by":{"1":"3, 28"},"q":[{"src":"brief","b":1,"text":"repealed the [INA’s] old judicial-review scheme * * * and instituted a new (and significantly more restrictive one) in 8 U.S.C. § 1252.","cite":"525 U.S. 471, 475"},{"src":"brief","b":1,"text":"protect[ion of ] the Executive’s discretion from the courts.","cite":"525 U.S. 471, 486"}]},{"t":"case","label":"SEC v. Central-Ill. Sec. Corp.","cite":"338 U.S. 96","y":1949,"id":"scdb/1948-120","sc":1,"by":{"1":"44"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"by":{"1":"17"}},{"t":"case","label":"Turri v. INS","cite":"997 F.3d 1306","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/1306/","by":{"1":"28"}},{"t":"case","label":"U.S. Bank Nat’l Ass’n v. Village at Lakeridge, LLC","cite":"138 S. Ct. 960","y":2018,"id":"2017/15-1509","sc":1,"by":{"1":"18, 21","2":"5, 11, 15"},"q":[{"src":"brief","b":1,"text":"‘basic’ or ‘historical’ fact[s]—addressing questions of who did what, when or where, how or why.","cite":"138 S. Ct. at 966"}]},{"t":"case","label":"United States v. Yellow Cab Co.","cite":"338 U.S. 338","y":1949,"id":"scdb/1949-016","sc":1,"by":{"1":"20"}},{"t":"case","label":"Wainwright v. Witt","cite":"469 U.S. 412","y":1985,"id":"1984/83-1427","sc":1,"by":{"1":"31"}},{"t":"case","label":"Weyerhauser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"by":{"1":"44","2":"9"}},{"t":"case","label":"Williamsport Wire Rope Co. v. United States","cite":"277 U.S. 551","y":1928,"id":"scdb/1927-126","sc":1,"by":{"1":"10, 15, 22, 23, 25, 26, 30","2":"11, 13, 16, 17"},"q":[{"src":"brief","b":1,"text":"facts concerning the situation of a large group","cite":"277 U.S. at 561"},{"src":"argument","who":"Ms. Sinzdak","text":"… s this a statute that's asking for a legal conclusion, like fair use, or is this a statute that's saying find a fact or -- like in Pullman-Standard where we had intention to discriminate, pure question of fact, or is it a statute where the terminology is saying make a discretionary decision like in Williamsport Wire Rope, where we had the term \"exceptional hardship\" and the Court said that's requiring a -- a discretionary decision. …"},{"src":"argument","who":"Ms. Sinzdak","text":"So I think that Pullman-Standard, Williamsport Wire Rope, and Duberstein are all good examples of cases where you had a statute and it required some subsidiary fact-finding and then the adjudicator had to put those subsidiary facts together to make an ultimate determination that was -- that was exactly the statutory text."},{"src":"argument","who":"Ms. Sinzdak","text":"So, to be clear, in Williamsport Wire Rope, it was not reviewable. And, there, it just depends on --"}]},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"31"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)"],"by":{"1":"44"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"44"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"1":"15, 20, 37-39"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(h)"],"by":{"1":"15"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)"],"by":{"1":"2, 2"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(1)(B)(iii)"],"by":{"1":"15"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(c)(4)(A)","(c)(4)(C)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4, 15","2":"25"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(b)(1)","(b)(1)(D)","(b)(1)(B)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"by":{"1":"13, 45, 2, 5, 8, 10-13, 23, 25","2":"18, 25"},"q":[{"src":"brief","b":1,"text":"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien’s spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence.","cite":"8 U.S.C. 1229b(b)(1)"},{"src":"brief","b":1,"text":"establish[] that removal would result in exceptional and extremely unusual hardship","cite":"8 U.S.C. 1229b(b)(1)(D)"}]},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(2)","(a)(2)(B)","(a)(2)(B)(i)","(a)(2)(D)","(a)(2)(B)(ii)","(b)(9)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4, 4, 9, 4, 13, 28, 5, 9, 12-18, 31, 33-35, 41, 42, 44-47, 4, 5, 9, 10, 12-14, 17, 18, 23, 29, 31-33, 42, 43, 45, 46","2":"19, 19, 20, 24, 19, 14, 19, 20, 4, 5"},"q":[{"src":"brief","b":1,"text":"[n]othing in subparagraph (B) or (C), or in any other provision of [the INA] (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review.","cite":"8 U.S.C. 1252(a)(2)(D)"},{"src":"brief","b":1,"text":"constitutional claims or questions of law,","cite":"8 U.S.C. 1252(a)(2)(D)"}]},{"t":"usc","label":"8 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/8/1254","subs":["(a)(1)(1964)","(a)(2)(1964)"],"by":{"1":"3, 3, 27"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"1":"4"}},{"t":"case","label":"Antoine-Dorcelli v. INS","cite":"703 F.2d 19","y":1983,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/703/19/","by":{"2":"24"}},{"t":"case","label":"Blanco v. INS","cite":"68 F.3d 642","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/68/642/","by":{"2":"24"}},{"t":"case","label":"Buffalo Courier-Express, Inc. v. Buffalo Evening News, Inc.","cite":"601 F.2d 48","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/601/48/","by":{"2":"8"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"2":"24"},"q":[{"src":"argument","who":"Ms. Santos","text":"It used its -- its purported authority under Chevron to interpret that standard using the canons of statutory construction that courts use day in and day out."}]},{"t":"case","label":"City of Escondido v. Emmons","cite":"139 S. Ct. 500","y":2019,"id":"2018/17-1660","sc":1,"by":{"2":"17"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"by":{"2":"17"}},{"t":"case","label":"Hernandez-Patino v. INS.","cite":"831 F.2d 750","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/831/750/","by":{"2":"24"}},{"t":"case","label":"Maslenjak v. United States","cite":"582 U.S. 335","y":2017,"id":"2016/16-309","sc":1,"by":{"2":"18"}},{"t":"case","label":"McLane Co. v. EEOC","cite":"581 U.S. 72","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/72/","sc":1,"by":{"2":"8, 9, 10"},"q":[{"src":"brief","b":2,"text":"free from the constraints which characteristically attach whenever legal rules enter the decisionmaking process.","cite":"581 U.S. 72, 83"},{"src":"brief","b":2,"text":"is given ‘an unusual amount of insulation from appellate revision’ for functional reasons.","cite":"581 U.S. at 83"}]},{"t":"case","label":"Metlyn Realty Corp. v. Esmark, Inc.","cite":"763 F.2d 826","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/763/826/","by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"There is discretion and then there is discretion.","cite":"763 F.2d 826, 831"}]},{"t":"case","label":"Nkomo v. Attorney General","cite":"986 F.3d 268","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/986/268/","by":{"2":"12"}},{"t":"case","label":"Patel v. U.S. Attorney General","cite":"971 F.3d 1258","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/971/1258/","by":{"2":"9"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"2":"16"}},{"t":"case","label":"Sandin v. Conner","cite":"515 U.S. 472","y":1995,"id":"1994/93-1911","sc":1,"by":{"2":"12"}},{"t":"case","label":"Seaboard Air Line Ry. v. United States","cite":"254 U.S. 57","y":1920,"id":"scdb/1920-044","sc":1,"by":{"2":"17"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"normally presume that the same language in related statutes carries a consistent meaning.","cite":"139 S. Ct. 2319, 2329"}]},{"t":"usc","label":"8 U.S.C. § 1186a","url":"https://www.law.cornell.edu/uscode/text/8/1186a","subs":["(c)(4)(B)","(c)(4)(C)","(c)(4)(D)"],"by":{"2":"18, 18, 18"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(l)"],"by":{"2":"24"}},{"t":"usc","label":"35 U.S.C. § 285","url":"https://www.law.cornell.edu/uscode/text/35/285","by":{"2":"18"}}]};